## Real deflate streams (written by Python's zlib), shared by `tgzip` and the
## fuzzer, and with pmtiles-swift. Not a test file itself (`nimble test` only
## runs `tests/t*.nim`).

import std/base64

proc bytes*(s: string): seq[byte] =
  let d = decode(s)
  result = newSeq[byte](d.len)
  for i, c in d: result[i] = byte(c)

const vectors* = [
  ("dynamic", "", 0xB20493AE'u32, 2568),
  ("fixed", "", 0xB20493AE'u32, 2568),
